const sizeClasses = {
  sm: "text-xs gap-1.5",
  md: "text-sm gap-2",
  lg: "text-base gap-2.5",
}

const iconSizeClasses = {
  sm: "[&_svg]:h-4",
  md: "[&_svg]:h-5",
  lg: "[&_svg]:h-6",
}

export interface BaselineStatusProps
  extends React.HTMLAttributes<HTMLDivElement> {
  /** Feature ID from web-features (e.g., "scroll-snap", "container-queries") */
  featureId?: string
  /** Direct status override (use instead of featureId for static data) */
  status?: BaselineStatusType
  /** Year when the feature became Baseline Newly available */
  year?: number
  /** Size variant */
  size?: "sm" | "md" | "lg"
  /** Show year in the label */
  showYear?: boolean
  /** Show only the icon without text */
  iconOnly?: boolean
  /**
   * Check whether the visitor's browser supports the feature and show it
   * next to the Baseline status.
   * - a known feature id (e.g. `"popover"`): built-in check
   * - `true`: built-in check for `featureId`
   * - `{ css: [property, value] }`, `{ selector }` or `{ test }`: custom check,
   *   with an optional `label` for the feature name
   * No row is shown when the feature has no check.
   */
  browserCheck?: BrowserFeature | true | BrowserCheck
  /** Override the texts of the browser check row (English by default) */
  labels?: {
    /** Shown before the feature name when supported */
    supported?: string
    /** Shown before the feature name when not supported */
    notSupported?: string
  }
}

/**
 * BaselineStatus displays browser support status for web features
 * based on the W3C WebDX Baseline specification.
 *
 * @see https://web.dev/baseline
 * @see https://github.com/web-platform-dx/web-features
 *
 * @example
 * // With featureId (fetched in the browser from api.webstatus.dev)
 * <BaselineStatus featureId="scroll-snap" />
 *
 * @example
 * // With static data (no API call)
 * <BaselineStatus status="widely" year={2022} />
 *
 * @example
 * // Icon only
 * <BaselineStatus featureId="container-queries" iconOnly />
 */
export function BaselineStatus({
  featureId,
  status: statusProp,
  year: yearProp,
  size = "md",
  showYear = true,
  iconOnly = false,
  browserCheck,
  labels,
  className,
  ...props
}: BaselineStatusProps) {
  const [feature, setFeature] = React.useState<BaselineFeature | null>(
    statusProp ? { status: statusProp, year: yearProp } : null,
  )
  const [isLoading, setIsLoading] = React.useState(!statusProp && !!featureId)
  const [browserSupport, setBrowserSupport] = React.useState<boolean | null>(
    null,
  )

  React.useEffect(() => {
    if (statusProp || !featureId) return

    let cancelled = false
    setIsLoading(true)

    getBaselineStatus(featureId).then((data) => {
      if (!cancelled) {
        setFeature(data)
        setIsLoading(false)
      }
    })

    return () => {
      cancelled = true
    }
  }, [featureId, statusProp])

  const check = resolveBrowserCheck(browserCheck, featureId)

  // Check browser support on mount. `browserCheck` may be an inline object, so
  // this runs after every render; setState bails out when the result is equal
  React.useEffect(() => {
    setBrowserSupport(check ? check.run() : null)
  })

  if (isLoading) {
    return (
      <div
        className={cn(
          "inline-flex items-center animate-pulse",
          sizeClasses[size],
          className,
        )}
        {...props}
      >
        <div className="h-5 w-9 rounded-full bg-muted" />
        {!iconOnly && <div className="h-4 w-24 rounded bg-muted" />}
      </div>
    )
  }

  const status = feature?.status ?? "no_data"
  const year = showYear ? feature?.year : undefined
  const label = getBaselineStatusText(status, year)
  const icon = BaselineIcons[status]

  // If the feature has a check, render the combined layout. Until the check
  // has run (server render, first paint) the row is kept invisible so the
  // layout does not jump
  if (check) {
    const featureLabel = check.label
    const pending = browserSupport === null
    const supported = browserSupport !== false

    return (
      <div
        className={cn(
          "inline-flex flex-wrap items-center gap-3 rounded-lg border border-border/50 bg-muted/30 px-3 py-2",
          className,
        )}
        role="status"
        {...props}
      >
        {/* Baseline Status */}
        <div
          className={cn(
            "flex items-center",
            sizeClasses[size],
            iconSizeClasses[size],
          )}
        >
          {icon}
          {!iconOnly && (
            <span className="text-muted-foreground whitespace-nowrap">
              {label}
            </span>
          )}
        </div>

        {/* Browser Support Check */}
        <div
          className={cn(
            "flex items-center gap-1.5 text-sm",
            pending && "invisible",
            supported
              ? "text-green-600 dark:text-green-400"
              : "text-red-600 dark:text-red-400",
          )}
          aria-hidden={pending || undefined}
        >
          {supported ? (
            <CheckCircle2 className="h-4 w-4 shrink-0" />
          ) : (
            <XCircle className="h-4 w-4 shrink-0" />
          )}
          <span>
            {supported
              ? (labels?.supported ?? "Your browser supports")
              : (labels?.notSupported ?? "Your browser does not support")}{" "}
            {featureLabel}
          </span>
        </div>
      </div>
    )
  }

  return (
    <div
      className={cn(
        "inline-flex items-center",
        sizeClasses[size],
        iconSizeClasses[size],
        className,
      )}
      role="status"
      aria-label={label}
      {...props}
    >
      {icon}
      {!iconOnly && (
        <span className="text-muted-foreground whitespace-nowrap">{label}</span>
      )}
    </div>
  )
}

/**
 * Static (non-hook) version of BaselineStatus, usable in Server Components.
 * Fetch the data on the server with getBaselineStatus and pass it in
 *
 * @example
 * // In a Server Component
 * const feature = await getBaselineStatus("scroll-snap")
 * <BaselineStatusStatic {...feature} />
 */
export function BaselineStatusStatic({
  status,
  year,
  size = "md",
  showYear = true,
  iconOnly = false,
  className,
  ...props
}: Omit<BaselineStatusProps, "featureId"> & {
  status: BaselineStatusType
}) {
  const label = getBaselineStatusText(status, showYear ? year : undefined)
  const icon = BaselineIcons[status]

  return (
    <div
      className={cn(
        "inline-flex items-center",
        sizeClasses[size],
        iconSizeClasses[size],
        className,
      )}
      role="status"
      aria-label={label}
      {...props}
    >
      {icon}
      {!iconOnly && (
        <span className="text-muted-foreground whitespace-nowrap">{label}</span>
      )}
    </div>
  )
}

/**
 * Baseline API utility for fetching web feature browser support status
 * @see https://web.dev/baseline
 * @see https://api.webstatus.dev/v1/features/
 */

const BASELINE_API = "https://api.webstatus.dev/v1/features"

export type BaselineStatus = "widely" | "newly" | "limited" | "no_data"

export interface BaselineFeature {
  status: BaselineStatus
  lowDate?: string // "2020-01-15" - when feature became newly available
  highDate?: string // "2022-07-15" - when feature became widely available
  year?: number // year of lowDate (Baseline Newly available)
  /** Official English feature name from webstatus.dev (not translated) */
  name?: string
}

export interface BrowserImplementation {
  date: string
  status: "available" | "unavailable"
  version: string
}

export interface BaselineAPIResponse {
  baseline: {
    status: "widely" | "newly" | "limited"
    low_date?: string
    high_date?: string
  } | null
  browser_implementations?: Record<string, BrowserImplementation>
  feature_id: string
  name: string
}

const cache = new Map<string, Promise<BaselineFeature>>()

/** Year from an ISO date ("2026-10-27"), without timezone shifts */
function yearOf(date?: string): number | undefined {
  const year = Number(date?.slice(0, 4))
  return Number.isInteger(year) && year > 1990 ? year : undefined
}

async function fetchBaselineStatus(
  featureId: string,
): Promise<BaselineFeature> {
  try {
    const response = await fetch(
      `${BASELINE_API}/${encodeURIComponent(featureId)}`,
      {
        next: { revalidate: 86400 }, // Cache for 24 hours (server only)
        signal: AbortSignal.timeout(8000),
      },
    )

    if (!response.ok) {
      console.warn(
        response.status === 404
          ? `Baseline API: feature "${featureId}" not found`
          : `Baseline API: HTTP ${response.status} for "${featureId}"`,
      )
      return { status: "no_data" }
    }

    const data: BaselineAPIResponse = await response.json()

    if (!data.baseline) {
      return { status: "no_data", name: data.name }
    }

    const { status, low_date, high_date } = data.baseline
    const name = data.name

    // Like the official <baseline-status>: the year is always the year when
    // the feature became Baseline Newly available (low_date). For widely
    // available features this is "available across browsers since <low_date>".
    return {
      status,
      lowDate: low_date,
      highDate: high_date,
      year: yearOf(low_date),
      name,
    }
  } catch (error) {
    console.error(`Baseline API error for "${featureId}":`, error)
    return { status: "no_data" }
  }
}

/**
 * Fetches Baseline status for a web feature.
 * Never throws: network errors, 404 and missing data resolve to "no_data".
 * Successful results are deduplicated per featureId; failures are retried.
 */
export function getBaselineStatus(featureId: string): Promise<BaselineFeature> {
  const cached = cache.get(featureId)
  if (cached) return cached

  const request = fetchBaselineStatus(featureId).then((feature) => {
    if (feature.status === "no_data") cache.delete(featureId)
    return feature
  })
  cache.set(featureId, request)
  return request
}

/**
 * Get display text for Baseline status
 * (official wording: "Baseline Widely available", "Baseline Newly available",
 * "Limited availability")
 */
export function getBaselineStatusText(
  status: BaselineStatus,
  year?: number,
): string {
  switch (status) {
    case "widely":
      return year
        ? `Baseline Widely available since ${year}`
        : "Baseline Widely available"
    case "newly":
      return year
        ? `Baseline Newly available since ${year}`
        : "Baseline Newly available"
    case "limited":
      return "Limited availability"
    default:
      return "No data"
  }
}

/**
 * Common feature IDs for reference
 * @see https://github.com/web-platform-dx/web-features/tree/main/features
 */
export const FEATURE_IDS = {
  // CSS
  scrollSnap: "scroll-snap",
  containerQueries: "container-queries",
  cssGrid: "css-grid",
  flexbox: "flexbox",
  cssVariables: "css-variables",
  anchorPositioning: "anchor-positioning",
  viewTransitions: "view-transitions",
  popover: "popover",

  // JavaScript
  promises: "promises",
  asyncAwait: "async-await",
  modules: "modules",

  // APIs
  intersectionObserver: "intersection-observer",
  resizeObserver: "resize-observer",
  webAnimations: "web-animations",
} as const

/**
 * Runtime browser checks for Baseline features.
 *
 * Maps a web-features `featureId` to a feature test that runs in the visitor's
 * browser, plus a human-readable name for the "Your browser supports …" line.
 * Used by BaselineStatus (`browserCheck`). No dependencies.
 *
 * Every test is a real detection (CSS.supports, an API on a prototype or a
 * parsed rule), never a user-agent guess. Features that cannot be detected
 * honestly are left out of the table, so no check line is shown for them.
 */

/** How to detect a feature. Use one of `css`, `selector` or `test`. */
export interface BrowserCheck {
  /** `CSS.supports(property, value)` */
  css?: [property: string, value: string]
  /** `CSS.supports("selector(<selector>)")`, e.g. `":has(*)"` */
  selector?: string
  /** Custom detection for APIs and at-rules */
  test?: () => boolean
  /** Name of the feature in "Your browser supports {label}" */
  label?: string
}

const cssSupports = (property: string, value: string): boolean =>
  typeof CSS !== "undefined" &&
  typeof CSS.supports === "function" &&
  CSS.supports(property, value)

const selectorSupports = (selector: string): boolean =>
  typeof CSS !== "undefined" &&
  typeof CSS.supports === "function" &&
  CSS.supports(`selector(${selector})`)

const inWindow = (name: string): boolean =>
  typeof window !== "undefined" && name in window

/** Detects `hidden="until-found"`: unsupported browsers coerce it to `true` */
const hiddenUntilFound = (): boolean => {
  const el = document.createElement("div") as unknown as { hidden: unknown }
  el.hidden = "until-found"
  return el.hidden === "until-found"
}

/** Parses a nested rule: browsers without CSS nesting drop it */
const cssNesting = (): boolean => {
  const sheet = new CSSStyleSheet()
  sheet.replaceSync(".a{.b{color:red}}")
  const rule = sheet.cssRules[0] as CSSStyleRule | undefined
  return rule?.cssRules?.length === 1
}

/**
 * Vertical `writing-mode` on form controls: a horizontal range input is wider
 * than it is tall, a vertical one is the other way round. Measures a hidden
 * element, so it is the only check that touches layout.
 */
const verticalFormControls = (): boolean => {
  const input = document.createElement("input")
  input.type = "range"
  input.setAttribute("aria-hidden", "true")
  input.style.cssText =
    "position:absolute;visibility:hidden;pointer-events:none;width:auto;height:auto;max-width:none;writing-mode:vertical-lr"
  document.body.appendChild(input)
  const { width, height } = input.getBoundingClientRect()
  input.remove()
  return height > width
}

